generate.initial_sparql:
PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?category ?avgReturnsPct ?avgSharpeRatio ?avgRiskScore
WHERE {
  {
    SELECT ?category (AVG(xsd:decimal(?returnsPct)) AS ?avgReturnsPct)
    WHERE {
      ?holding a wm:PortfolioHolding ;
               wm:returnsPct ?returnsPct ;
               wm:hasCategory ?category .
    }
    GROUP BY ?category
  }
  {
    SELECT ?category (AVG(xsd:decimal(?investorSharpe)) AS ?avgSharpeRatio) (AVG(xsd:decimal(?investorRisk)) AS ?avgRiskScore)
    WHERE {
      ?holding a wm:PortfolioHolding ;
               wm:investorId ?investorId ;
               wm:hasCategory ?category .
      {
        SELECT ?investorId (AVG(xsd:decimal(?avgSharpeRatio)) AS ?investorSharpe) (AVG(xsd:decimal(?riskScore)) AS ?investorRisk)
        WHERE {
          OPTIONAL {
            ?goal a wm:InvestmentGoal ;
                  wm:investorId ?investorId ;
                  wm:avgSharpeRatio ?avgSharpeRatio .
          }
          OPTIONAL {
            ?health a wm:PortfolioHealth ;
                    wm:investorId ?investorId ;
                    wm:riskScore ?riskScore .
          }
        }
        GROUP BY ?investorId
      }
    }
    GROUP BY ?category
  }
}

